socket.on('data', chunk => {
    if (settled) return;
    buffer = Buffer.concat([buffer, chunk]);
    try {
        if (buffer.length < 16) return;
        if (buffer[0] !== 0x5a || buffer[1] !== 1) throw new Error('Invalid SEER response header');
